 import unittest
from candidate import is_multiply_prime, is_prime

class TestIsMultiplyPrime(unittest.TestCase):
    def test_multiply_prime_normalcase(self):
        self.assertTrue(is_multiply_prime(30))

    def test_multiply_prime_boundary_case(self):
        self.assertTrue(is_multiply_prime(99))

    def test_multiply_prime_less_than_100(self):
        self.assertTrue(is_multiply_prime(98))

    def test_multiply_prime_not_100(self):
        self.assertFalse(is_multiply_prime(101))

    def test_multiply_prime_prime_number(self):
        self.assertTrue(is_multiply_prime(7))

    def test_multiply_prime_non_prime_number(self):
        self.assertFalse(is_multiply_prime(12))

    def test_multiply_prime_empty_range(self):
        self.assertFalse(is_multiply_prime(1))

    def test_multiply_prime_too_many_factors(self):
        self.assertFalse(is_multiply_prime(600))

    def test_multiply_prime_incorrect_factors(self):
        self.assertFalse(is_multiply_prime(400))

    def test_is_prime_normal_case(self):
        self.assertTrue(is_prime(2))
        self.assertTrue(is_prime(3))
        self.assertTrue(is_prime(5))

    def test_is_prime_boundary_case(self):
        self.assertTrue(is_prime(97))

    def test_is_prime_greater_than_100(self):
        self.assertFalse(is_prime(101))

    def test_is_prime_non_prime_number(self):
        self.assertFalse(is_prime(4))
        self.assertFalse(is_prime(6))
        self.assertFalse(is_prime(8))

    def test_is_prime_small_numbers(self):
        self.assertTrue(is_prime(0))
        self.assertTrue(is_prime(1))

    def test_is_prime_zero(self):
        self.assertFalse(is_prime(0))

    def test_is_prime_negative_numbers(self):
        self.assertFalse(is_prime(-1))
        self.assertFalse(is_prime(-2))
        self.assertFalse(is_prime(-3))

if __name__ == '__main__':
    unittest.main()
